using SoulsFormats;using System.Numerics;using System.Security.Cryptography;using System.Text.Json;
static class MapCrestGateAudit {
static void Main(string[] args){string root=args[0],output=args[1];Directory.CreateDirectory(output);var hashes=new Dictionary<string,string>();byte[] Read(string p){var path=Path.Combine(root,p);var b=File.ReadAllBytes(path);hashes[path]=Convert.ToHexStringLower(SHA256.HashData(b));return b;}
var source=MSB1.Read(Read("map/MapStudio/m12_00_00_00.msb"));var objects=source.Parts.Objects.Where(p=>p.EntityID is 1201000 or 1201010).ToArray();File.WriteAllText(Path.Combine(output,"placements.json"),JsonSerializer.Serialize(new{Objects=objects.Select(p=>new{p.Name,p.ModelName,p.EntityID,p.Position,p.Rotation,p.Scale,p.InitAnimID,p.CollisionName}),Regions=source.Regions.GetEntries().Where(r=>r.EntityID is 1202500 or 1202501).Select(r=>new{r.Name,r.EntityID,r.Position,r.Rotation,Type=r.Shape.GetType().Name}),Vfx=source.Events.SFX.Where(v=>v.EntityID is 120020 or 120021)},new JsonSerializerOptions{WriteIndented=true,IncludeFields=true}));
foreach(string model in objects.Select(p=>p.ModelName).Distinct()){var b=Read("obj/"+model+".objbnd.dcx");var bank=BND3.Read(b);var v=FLVER2.Read(bank.Files.Single(f=>f.ID==200).Bytes);var a=BND3.Read(bank.Files.Single(f=>f.ID==400).Bytes);var raw=bank.Files.Single(f=>f.ID==300).Bytes.ToArray();var t=new SourceCollision.Tag(raw);var bodies=new List<object>();foreach(var body in t.Items.Where(i=>i.Count==1&&t.Name(i.Type)=="hkpRigidBody")){var name=t.Reference(t.Nested(body.Type,body.At,"name").At);var shape=t.Reference(t.Nested(body.Type,body.At,"collidable","shape").At);string type=t.Name(shape.Type);var child=type=="hkpConvexTranslateShape"?t.Reference(t.Nested(shape.Type,shape.At,"childShape","childShape").At):shape;bodies.Add(new{Name=SourceAnimation.DecodeBoneName(raw.AsSpan(name.At,name.Count-1).ToArray()),Type=type,Child=t.Name(child.Type),Half=t.Name(child.Type)=="hkpBoxShape"?t.Vector(t.Nested(child.Type,child.At,"halfExtents").At):Vector3.Zero,Translation=type=="hkpConvexTranslateShape"?t.Vector(t.Nested(shape.Type,shape.At,"translation").At):Vector3.Zero,Rest=t.Transform(t.Nested(body.Type,body.At,"motion","motionState","transform").At)});}
var clips=a.Files.Where(f=>f.ID<10000).Select(f=>{var c=SourceAnimation.Decode(a.Files.Single(f=>f.ID==1000000).Bytes.ToArray(),f.Bytes.ToArray());return new{f.ID,f.Name,c.FrameCount,c.Duration,c.FrameDuration,Bones=c.Bones.Select((n,i)=>new{Index=i,n.Name,n.Parent,n.Translation,n.Rotation,n.Scale}),Start=c.Sample(0),Middle=c.Sample(c.Duration/2),End=c.Sample(c.Duration)};});File.WriteAllText(Path.Combine(output,model+"-assets.json"),JsonSerializer.Serialize(new{Hash=Convert.ToHexStringLower(SHA256.HashData(b)),Files=bank.Files.Select(f=>new{f.ID,f.Name,Length=f.Bytes.Length}),Nodes=v.Nodes.Select((n,i)=>new{Index=i,n.Name,n.ParentIndex,n.Translation,n.Rotation,n.Scale}),Dummies=v.Dummies.Select(d=>new{d.ReferenceID,d.ParentBoneIndex,d.AttachBoneIndex,d.Position,d.Forward,d.Upward}),Meshes=v.Meshes.Select(m=>new{m.MaterialIndex,m.Dynamic,m.UseBoneWeights,Vertices=m.Vertices.Count,Nodes=m.Vertices.Select(x=>x.BoneIndices[0]).Distinct().ToArray(),m.BoneIndices}),Bodies=bodies,Clips=clips},new JsonSerializerOptions{WriteIndented=true,IncludeFields=true}));}
if(args.Length>2){var ng=BND4.Read(File.ReadAllBytes(Path.Combine(args[2],"param/gameparam/gameparam.parambnd.dcx")));var nt=PARAM.Read(ng.Files.Single(f=>Path.GetFileName(f.Name.Replace('\\','/'))=="ActionButtonParam.param").Bytes);var def=new PARAMDEF{ParamType=nt.ParamType,DataVersion=nt.ParamdefDataVersion,Unicode=true};def.Fields.Add(new PARAMDEF.Field(def,PARAMDEF.DefType.dummy8,"payload"){ArrayLength=72});nt.ApplyParamdef(def);File.WriteAllText(Path.Combine(output,"native-actionbuttons.json"),JsonSerializer.Serialize(nt.Rows.Where(r=>r.ID is 7000 or 7001 or 2410041).Select(r=>new{r.ID,r.Name,Hex=Convert.ToHexString((byte[])r.Cells.Single().Value)}),new JsonSerializerOptions{WriteIndented=true}));}var script=EMEVD.Read(Read("event/m12_00_00_00.emevd.dcx"));File.WriteAllText(Path.Combine(output,"source-events.json"),JsonSerializer.Serialize(script.Events.Where(e=>e.ID is 11200100 or 11200110 or 0).Select(e=>new{e.ID,e.RestBehavior,Instructions=e.Instructions.Select(i=>new{i.Bank,i.ID,Hex=Convert.ToHexString(i.ArgData)}),Parameters=e.Parameters.Select(p=>new{p.InstructionIndex,p.TargetStartByte,p.SourceStartByte,p.ByteCount})}),new JsonSerializerOptions{WriteIndented=true}));foreach(var(path,h)in hashes)if(Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)))!=h)throw new Exception("Input mutated");File.WriteAllText(Path.Combine(output,"hashes.json"),JsonSerializer.Serialize(hashes,new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine("PASS Crest gate actual resource audit; "+hashes.Count+" originals unchanged");}}
